/// The blocks of `role` of capture `capture`, in the order they were sent.
inline std::vector<const Block*> find_all(uint16_t capture, const char* role) {
    std::vector<const Block*> out;
    for (const Block& b : kBlocks) {
        if (b.capture == capture && std::strcmp(b.role, role) == 0) out.push_back(&b);
    }
    return out;
}

/// The first block of `role` of capture `capture` (nullptr: none).
inline const Block* find(uint16_t capture, const char* role) {
    const auto all = find_all(capture, role);
    return all.empty() ? nullptr : all.front();
}

